import { Project } from '../../src'

describe('Fluent ignore tests', () => {
    // FIXME: TablePlugin doesn't seem to be outputting the expected diagnostics
    test.skip('@fluent-ignore directive should suppress diagnostics emerging from fluent file.', async () => {
        const code = `
            import { ClientScript, Table } from '@servicenow/sdk/core'
            
            ClientScript({
                $id: '123',
                name: 'test',
                /* TS_PLACEHOLDER */
                table: true, // <-------------------- DIAGNOSTIC #1: Boolean is not allowed here (TS)
                // TS_PLACEHOLDER
                script: 123 // <--------------------- DIAGNOSTIC #2: Number is not allowed here (TS)
            })
             
            /* FL_PLACEHOLDER */
            Table({ // <----------------------------- DIAGNOSTIC #3: Not exported correctly (Fluent)
                // FL_PLACEHOLDER
                name: 'x_wrong_prefix_table_one', // <--- DIAGNOSTIC #4: Doesn't have correct scope prefix (Fluent)
                schema: {},
            })
             
            // FL_PLACEHOLDER
            Table({ // <----------------------------- DIAGNOSTIC #5: Same as above (Fluent)
                /* FL_PLACEHOLDER */
                name: 'x_wrong_prefix_table_two', // <--- DIAGNOSTIC #6: Same as above (Fluent)
                schema: {},
            })
             
            Table({ // <----------------------------- DIAGNOSTIC #7: Same as above (Fluent) (not ignored)
                name: 'x_wrong_prefix_table_two', // <--- DIAGNOSTIC #8: Same as above (Fluent) (not ignored)
                schema: {},
            })`

        const codeWithTsIgnore = code.replace(/TS_PLACEHOLDER/g, '@ts-ignore')
        const codeWithFluentIgnore = codeWithTsIgnore.replace(/FL_PLACEHOLDER/g, '@fluent-ignore')

        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        const file = project.addFile({ path: 'src/fluent/index.now.ts', content: code })
        const fileWithTsIgnore = project.addFile({ path: 'src/fluent/ts-ignored.now.ts', content: codeWithTsIgnore })
        const fileWithFluentIgnore = project.addFile({
            path: 'src/fluent/fl-ignored.now.ts',
            content: codeWithFluentIgnore,
        })

        const fileDiagnostics = await file.getDiagnostics()
        const fileWithTsIgnoreDiagnostics = await fileWithTsIgnore.getDiagnostics()
        const fileWithFluentIgnoreDiagnostics = await fileWithFluentIgnore.getDiagnostics()

        expect(fileDiagnostics).toHaveLength(2) // Only TS diagnostics because TS errors will prevent Fluent compilation
        expect(fileWithTsIgnoreDiagnostics).toHaveLength(6) // TS errors are ignored, but Fluent errors are not
        expect(fileWithFluentIgnoreDiagnostics).toHaveLength(2) // All errors except the last two Fluent errors are ignored
    })
})
